use dotstate::config::Config;
use dotstate::screens::settings::SettingItem;
use tempfile::TempDir;

#[test]
fn test_automatic_update_checks_setting_name() {
    // Verify the setting name is "Automatic Update Checks" after rename
    let setting = SettingItem::CheckForUpdates;
    assert_eq!(setting.name(), "Automatic Update Checks");
}

#[test]
fn test_automatic_update_checks_apply_setting() {
    let temp_dir = TempDir::new().unwrap();
    let config_path = temp_dir.path().join("config.toml");
    let repo_path = temp_dir.path().join("repo");

    let mut config = Config {
        repo_path: repo_path.clone(),
        ..Default::default()
    };

    // Start with updates disabled
    config.updates.check_enabled = false;
    config.save(&config_path).unwrap();

    // Load the config
    let mut config = Config::load_or_create(&config_path).unwrap();
    assert!(!config.updates.check_enabled);

    // Apply the setting using the new name "Automatic Update Checks"
    // Option index 0 = Enabled
    SettingsScreen::apply_setting_to_config(&mut config, "Automatic Update Checks", 0);
    assert!(config.updates.check_enabled);

    // Apply the setting again with option index 1 = Disabled
    SettingsScreen::apply_setting_to_config(&mut config, "Automatic Update Checks", 1);
    assert!(!config.updates.check_enabled);
}

#[test]
fn test_automatic_update_checks_in_all_settings() {
    // Verify CheckForUpdates is included in the all() list
    let settings = SettingItem::all(dotstate::config::RepoMode::Local);
    assert!(settings.contains(&SettingItem::CheckForUpdates));

    // Find the setting and verify its name
    let update_setting = settings
        .iter()
        .find(|s| **s == SettingItem::CheckForUpdates)
        .unwrap();
    assert_eq!(update_setting.name(), "Automatic Update Checks");
}

#[test]
fn test_automatic_update_checks_persists() {
    let temp_dir = TempDir::new().unwrap();
    let config_path = temp_dir.path().join("config.toml");
    let repo_path = temp_dir.path().join("repo");

    // Create config with updates enabled
    let mut config = Config {
        repo_path: repo_path.clone(),
        ..Default::default()
    };
    config.updates.check_enabled = true;
    config.save(&config_path).unwrap();

    // Load it back and verify persistence
    let loaded = Config::load_or_create(&config_path).unwrap();
    assert!(loaded.updates.check_enabled);

    // Disable and save again
    let mut config = loaded;
    config.updates.check_enabled = false;
    config.save(&config_path).unwrap();

    // Load and verify the new state
    let loaded = Config::load_or_create(&config_path).unwrap();
    assert!(!loaded.updates.check_enabled);
}

// Helper struct for testing - mimics the public API of SettingsScreen
struct SettingsScreen;

impl SettingsScreen {
    fn apply_setting_to_config(
        config: &mut Config,
        setting_name: &str,
        option_index: usize,
    ) -> bool {
        Self::apply_setting_by_name(config, setting_name, option_index)
    }

    fn apply_setting_by_name(config: &mut Config, setting_name: &str, option_index: usize) -> bool {
        match setting_name {
            "Automatic Update Checks" => {
                config.updates.check_enabled = option_index == 0;
                return true;
            }
            _ => {}
        }
        false
    }
}

